    options: [L("1-2 kg", "1-2 కిలోలు", "1-2 கிலோ", "1-2 ಕೆಜಿ", "1-2 किलो"), L("4-6 kg", "4-6 కిలోలు", "4-6 கிலோ", "4-6 ಕೆಜಿ", "4-6 किलो"), L("15-20 kg", "15-20 కిలోలు", "15-20 கிலோ", "15-20 ಕೆಜಿ", "15-20 किलो"), L("50-60 kg", "50-60 కిలోలు", "50-60 கிலோ", "50-60 ಕೆಜಿ", "50-60 किलो")],
